<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {useStudies} from '../stores/studies';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import StudySelect from '../components/StudySelect.vue';const study=useStudies(),research=useResearch(),auth=useAuth(),router=useRouter(),{error,busy,perform}=useTask(),name=ref('形成错位 · 全组秩比较'),alpha=ref(.05),bootstrapSeed=ref(20261113),bootstrapReplicates=ref(9999);onMounted(()=>perform(async()=>{await study.load();await research.loadRuns()}));usePolling(research.loadRuns);async function submit(){await research.queue({study_id:study.selected,name:name.value,alpha:alpha.value,bootstrap_seed:bootstrapSeed.value,bootstrap_replicates:bootstrapReplicates.value});name.value='形成等级 · 复核 '+new Date().toLocaleTimeString()}function read(id:number){research.select(id);router.push('/results')}</script><template><PageHeading no="03" title="冻结与运行" sub="提前写明alpha，冻结全部预定义工艺与等级；不按结果挑选组对。"/><ErrorNotice :error="error"/><div class="run-spread"><section><StudySelect/><form class="run-form" @submit.prevent="perform(submit)"><label>检验名称<input v-model="name" required minLength="2" maxLength="140"/></label><label>预设显著性水平 α<input v-model.number="alpha" type="number" min="0.000001" max="0.999999" step="any" required/></label><label>Bootstrap 种子（随检验冻结，可复算）<input v-model.number="bootstrapSeed" type="number" min="0" max="4294967295" step="1" required/></label><label>组级重抽样次数（100–100000，随检验冻结）<input v-model.number="bootstrapReplicates" type="number" min="100" max="100000" step="100" required/></label><div class="method-note"><b>一次合并排秩，两层阅读</b><p>KW：平均秩、并列修正C、渐近χ²。</p><p>Dunn：全部k(k−1)/2组对，共用合并秩方差，双侧正态渐近p与Holm校正。</p><p>效应量：各工艺对优胜比例（胜+半并列）/总比较数；按组重抽样、保留组内n，同次抽样覆盖全部组对，以整族最大偏差百分位给出预设α下的同时区间（半径全族共享），重抽样无变异时退化为点估计。</p><p>种子与抽样次数写入冻结指纹；无论总体p是否达到α，完整组对都保留。未拒绝不等于证明相同。</p></div><button class="primary" :disabled="busy||!auth.canEdit">{{busy?'提交中…':'冻结全组并排队 →'}}</button><p v-if="!auth.canEdit" class="muted">观察员可阅读；请分析员提交计算。</p></form><aside class="margin-note"><b>全同值不作无差异结论</b><p>若全部等级相同，并列修正C=0，统计量未定义，任务明确失败。少于5份/组、空组或非法等级也会失败并保留原因。</p></aside></section><section><h2 class="ruled-title">后台检验队列 <small>{{research.runs.length}}项</small></h2><div v-if="!research.runs.length" class="empty">尚无检验。核对来源后，从左侧冻结一项完整研究。</div><article class="run-entry" v-for="r in research.runs" :key="r.id"><div class="entry-line"><small>RUN {{r.id}}</small><StatusBadge :status="r.status"/></div><h3>{{r.name}}</h3><p>{{r.snapshot.treatments.length}}工艺 / {{r.snapshot.readings.length}}份试样 / α {{r.alpha}}<template v-if="r.bootstrap_replicates!=null"> / 种子 {{r.bootstrap_seed}} × {{r.bootstrap_replicates}}次重抽样</template></p><small>{{date(r.created_at)}}</small><p v-if="r.error" class="error-text">{{r.error}}</p><button v-if="r.status==='completed'" class="text-link" @click="read(r.id)">打开完整检验结果 ↗</button><p v-if="['queued','running'].includes(r.status)" class="working">队列每2.5秒刷新，离开页面不影响后台执行。</p></article></section></div></template>